WITH base AS (SELECT id, device_code, reading_ts, temp_c, humidity, pressure, firmware, LOWER(device_code) AS device_code_lower, status_bits + humidity AS status_bits_plus_humidity FROM device_readings WHERE reading_ts > TO_TIMESTAMP('2025-09-01 14:00:00') AND humidity BETWEEN 35 AND 54), with_prev AS (SELECT *, LAG(reading_ts) OVER (PARTITION BY device_code ORDER BY reading_ts, id) AS prev_reading_ts FROM base), flagged AS (SELECT *, CASE WHEN prev_reading_ts IS NULL OR reading_ts > prev_reading_ts + INTERVAL '30' MINUTE THEN 1 ELSE 0 END AS session_start_flag FROM with_prev), sessionized AS (SELECT *, SUM(session_start_flag) OVER (PARTITION BY device_code ORDER BY reading_ts, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS burst_id FROM flagged) SELECT DATE_TRUNC('HOUR', reading_ts) AS hour_window, MIN(prev_reading_ts) AS first_seen, ROUND(SUM(status_bits_plus_humidity) / NULLIF(COUNT(CASE WHEN device_code = 'DV-02' THEN 1 END), 0), 2) AS status_bits_plus_humidity_per_dv_02 FROM sessionized GROUP BY hour_window
